import React from 'react';
import { createErrorBoundary } from '@sentry/react';

// Define ErrorComponent here
function ErrorComponent() {
  throw new Error('Test error');
}

// Create the ErrorBoundary component here
function ErrorBoundary({ children }: { children: React.ReactNode }) {
  const [hasError, setHasError] = React.useState(false);

  React.useEffect(() => {
    if (hasError) {
      throw new Error('Error occurred');
    }
  }, [hasError]);

  return children;
}

// Create the ErrorFallback component here
function ErrorFallback({ resetErrorBoundary }: { resetErrorBoundary: () => void }) {
  const handleRetry = () => {
    resetErrorBoundary();
  };

  return (
    <div>
      <h2>Something went wrong</h2>
      <button onClick={handleRetry}>Retry</button>
    </div>
  );
}

// Create the App component here
function App() {
  // Add state and button here

  return (
    <ErrorBoundary FallbackComponent={ErrorFallback}>
      <div>
        <h1>Error Boundary Test</h1>
        {/* Add trigger button and conditional rendering here */}
      </div>
    </ErrorBoundary>
  );
}

